<section class="member-hero"><span class="member-emblem"><?= icon('crown') ?></span><p class="eyebrow">GO A LITTLE FURTHER</p><h1><?= e($title) ?></h1><p><?= t('One membership. More room for your curiosity. Choose the duration that suits you.') ?></p><?php if ($me && (int)$me['vip_until']>time()): ?><span class="pill success"><?= t('Membership active until') ?> <?= membership_until((int)$me['vip_until']) ?></span><?php endif ?></section><?php if($me): ?><div class="membership-entitlements"><?php foreach($a->db->all('SELECT tier,until_at FROM cy_memberships WHERE user_id=? AND until_at>? ORDER BY tier DESC',[(int)$me['id'],time()]) as $grant): ?><span class="pill">VIP <?= (int)$grant['tier'] ?> / <?= membership_until((int)$grant['until_at']) ?></span><?php endforeach ?></div><?php endif ?><div class="plan-grid"><?php foreach ($plans as $index=>$plan): ?><article class="plan-card panel glass <?= $index===1?'featured':'' ?>"><?php if ($index===1): ?><span class="plan-badge"><?= t('A little more time to explore') ?></span><?php endif ?><span class="plan-icon"><?= icon('crown') ?></span><h2><?= e($plan['name']) ?> <span class="pill">VIP <?= (int)$plan['tier'] ?></span></h2><div class="plan-price"><?= e(price((int)$plan['price_amount'],$plan['price_currency'])) ?><small>/ <?= (int)$plan['days']===0?t('Lifetime'):(int)$plan['days'].' '.t('days') ?></small></div><?php if($me && $s->enabled('upgrades') && $a->membership->tier($me)>0 && $a->membership->tier($me)<(int)$plan['tier']): ?><a class="btn secondary full" href="<?= e(url('upgrade',['plan_id'=>$plan['id']])) ?>"><?= t('Preview upgrade credit') ?></a><?php endif ?><?php if($me && $s->enabled('checkout') && $plan['price_currency']==='balance' && $a->membership->lifetimeTier((int)$me['id'])<(int)$plan['tier']): ?><a class="btn secondary full" href="<?= e(url('checkout',['kind'=>'membership','item_id'=>$plan['id']])) ?>"><?= t('Direct payment checkout') ?></a><?php endif ?><div class="plan-description"><?= \Chengyu\Core\Markdown::render($plan['description']) ?></div><?php if ($me && $a->membership->lifetimeTier((int)$me['id'])>=(int)$plan['tier']): ?><span class="pill success"><?= t('Included in your lifetime membership') ?></span><?php elseif ($me): ?><?= form_start('buy') . intent() . hidden('kind','membership') . hidden('item_id',$plan['id']).hidden('price_ceiling',$plan['price_amount']).hidden('price_currency',$plan['price_currency']) ?><?php field('coupon','Coupon code (optional)'); button('Activate membership','full','arrow'); ?></form><?php else: ?><a class="btn full" href="<?= e(url('login')) ?>"><?= t('Sign in to join') ?><?= icon('arrow') ?></a><?php endif ?></article><?php endforeach ?></div><?php if (!$plans) {empty_state('No membership plans are available yet.','crown');} ?><div class="member-note"><?= icon('shield') ?><?= t('VIP 1-3 renew independently. A higher active tier includes lower-tier access. Buying a lower tier never extends a higher tier. No recurring billing.') ?></div>
